%[text] # **Vented Hydrogen Deflagration Experiments**
%[text] # **Preliminary Results Campaign Week 22 2026**
%[text] %[text:anchor:T_D5D49718] # Data Processing Procedure (DPP)
%%
%[text] # **Data Preparation (DPR)**
%[text] %[text:anchor:H_23C559C1] ## 1. Setup (Matlab Startup File)
%[text] %[text:anchor:H_1B29D089] This m-File code prepare the environment to provide access to auxiliary files and sub-folders.
clear ; clc; close all;
format short eng
scriptRoot = fileparts(mfilename("fullpath"));
[projectRoot,AuxFcn_GS] = AuxFcn_Matlab_Startup_File_001;
auxRoot = fullfile(projectRoot, ...
    "3-Calculations-Files", "Matlab-Files", "Auxilliary_Functions");
mainFcnRoot = fullfile(projectRoot, ...
    "3-Calculations-Files", "Matlab-Files", "Main_Functions");
addpath(genpath(auxRoot));
addpath(genpath(mainFcnRoot));
set(groot, 'defaultTextInterpreter', 'latex', 'defaultAxesTickLabelInterpreter','latex', 'defaultLegendInterpreter','latex');
%%
%[text] ## **2. Load & Overview of Raw Data Campaign**
%[text] #### **2.1 Load Raw Data Campaign**
%[text] #### **Campaign: VH2D-Wk22**
%[text] One-Time-Run to Generate File Structure of the Campaign
% campaigns = MainFcn_Load_VH2D_RawCampaign_001("VH2D_Wk22", ["02","03","04"]);
%[text] Load Group Raw Data
campaignMatFile = fullfile(projectRoot, ...
    "2-Data", "ConvertedData", "VH2D-Wk22", ...
    "VH2D_Wk22_Groups_02_03_04.mat");
load(campaignMatFile)
campaign = VH2D_Wk22;
%%
%[text] ## **3. Raw Data Overview**
%[text] The campaign cache contains the full raw data structure. The JSON metadata files are used only to build compact, readable overview tables for the report.
metadataRoot = fullfile(projectRoot, "2-Data", "RawData", "VH2D-Wk22", "Metadata");
metadata = AuxFcn_LoadVH2DMetadata_001(metadataRoot, Groups=["02","03","04"]);
rawDataOverviewTable = AuxFcn_BuildVH2DRawOverviewTable_001(campaign, metadata);
reportTables = AuxFcn_BuildVH2DRawReportTables_001(campaign, metadata);
%[text] ### **3.1 Raw Data Load Status**
rawLoadStatusTable = reportTables.rawLoadStatus;
rawLoadStatusDisplayTable = reportTables.rawLoadStatusDisplay;
fprintf('\n--- Raw Data Load Status ---\n\n'); %[output:36047e18]
disp(rawLoadStatusDisplayTable); %[output:2f97cd11]
%[text] ### 3.2 Channel Audit Summary
%[text] %[text:anchor:TMP_7ebd] (loaded channels vs. sensor mapping metadata)
daqSystemsToAudit = ["DAQ_1","DAQ_2_3","DAQ_4"];

[channelAuditTable, channelAuditSummaryTable, channelAuditWarningTable] = ...
    AuxFcn_BuildVH2DChannelAuditTable_001(campaign, metadata, ...
    DAQs=daqSystemsToAudit);
% Compact evidence overview: loaded channels plus expected metadata mapping.
fprintf('\n--- Channel Audit Summary ---\n\n'); %[output:4059cc16]
disp(channelAuditSummaryTable); %[output:875a4b29]

% Detailed rows only when the same loaded channel changes column across runs.
fprintf('\n--- Channel Audit Warnings Summary ---\n\n'); %[output:6db0c39f]
disp(channelAuditWarningTable); %[output:4800fd7d]
%[text] ### **3.3 Run Plan Summary**
runPlanTable = reportTables.runPlan;
fprintf('\n--- Run Plan Summary ---\n\n'); %[output:666729f6]
disp(runPlanTable); %[output:675d8e12]
%[text] ### **3.4 Gas Mixing Summary**
gasMixingTable = reportTables.gasMixing;
fprintf('\n--- Gas Mixing Summary ---\n\n'); %[output:445d1689]
disp(gasMixingTable); %[output:7deaa736]
%[text] ### **3.5 DAQ Systems Summary**
daqSystemsTable = reportTables.daqSystems;
fprintf('\n--- DAQ Systems Summary ---\n\n'); %[output:7e5f3c24]
disp(daqSystemsTable); %[output:33fa9c97]
%[text] ### **3.6 Pressure Sensor Mapping Summary**
sensorMappingTable = reportTables.sensorMap;
fprintf('\n--- Pressure Sensor Mapping Summary ---\n\n'); %[output:0d05c9b2]
disp(sensorMappingTable); %[output:29e42aa0]
%[text] ### **3.7 Group and Run Notes Table**
groupAndRunNotesTable = reportTables.groupAndRunNotes;
fprintf('\n--- Group and Run Notes ---\n\n'); %[output:5490ec05]
disp(groupAndRunNotesTable); %[output:55148cf7]
%%
%[text] ## **4. Data Preprocessing**
%[text] ### **4.1 Unit Conversion**
%[text] Pressure: bar to kPa and Concentration: ppm to vol.%
% Convert raw loaded units to analysis units while preserving the original
% raw campaign structure in `campaign`.
converted = AuxFcn_ConvertVH2DUnits_001(campaign);

conversionOverviewTable = converted.overview;
conversionSummaryTable = unique(conversionOverviewTable(:, ...
    {'DAQs','RawUnit','SourceUnit','SourceUnitEvidence', ...
    'TargetUnit','Factor','Status','Rule'}), 'rows');
fprintf('\n--- Unit Conversion Summary ---\n\n'); %[output:61e68e1d]
disp(conversionSummaryTable); %[output:09882ba3]
%[text] ### **4.2 Time Vectors Alignment**
%[text] Pressure Sensors Time aligned with Trigger at 4V define the zero time
% Use one common zero-time definition for all pressure/trigger DAQs:
% the first trigger crossing at 4 V. Signal values are not modified; only
% the time vectors are shifted.
aligned = AuxFcn_AlignVH2DTimeVectors_001(converted, ...
    TriggerZeroThreshold_V=4, ...
    DAQsToAlign=["DAQ_1","DAQ_2_3","DAQ_4"]);
alignmentOverviewTable = aligned.alignmentOverview;
alignmentSummaryDisplayTable = aligned.alignmentSummaryDisplayTable;
fprintf('\n--- Time Vectors Alignment Summary ---\n\n'); %[output:836f5642]
disp(alignmentSummaryDisplayTable); %[output:84d3856e]
%[text] #### **4.3** Remove DC Background Offset
% Remove DC background offset only from pressure channels. Trigger channels
% and concentration channels remain unchanged.
offsetCorrected = AuxFcn_RemoveVH2DPressureOffset_001(aligned, ...
    BaselineWindow_s=[-0.050, -0.005], ...
    KeepSourceSignal=false);

offsetOverviewTable = offsetCorrected.offsetOverview;
offsetSummaryTable = offsetOverviewTable(:, ...
    {'GroupId','RunId','DAQs','Column','Channel','Unit', ...
    'BaselineWindowStart_s','BaselineWindowEnd_s', ...
    'BaselineMean_kPa','BaselineStd_kPa','BaselineSamples','Status'});
fprintf('\n--- Remove DC Background Offset Summary ---\n\n'); %[output:097b8cea]
disp(offsetSummaryTable); %[output:22c18275]
%%
%[text] ## 5. **Pressure and Trigger Signal Preprocessed**
% Keep only the preliminary pressure/trigger analysis window to reduce memory
% and plotting cost. Concentration measurements are not processed here.
pressurePreprocessed = AuxFcn_PreprocVH2DPressureTriggerSignals_001( ...
    offsetCorrected, ...
    PreprocWindow_s=[-0.050, 1.75], ...
    DAQs=["DAQ_1","DAQ_2_3","DAQ_4"]);
pressurePreprocessedOverviewTable = pressurePreprocessed.preprocOverview;
pressurePreprocessedSummaryTable = pressurePreprocessedOverviewTable(:, ...
    {'GroupId','RunId','DAQs','PreprocStart_s','PreprocEnd_s', ...
    'SourceSamples','KeptSamples','RemovedSamples','Status'});
fprintf('\n--- Pressure and Trigger Preprocessed Signal Summary ---\n\n'); %[output:3d1e6d6b]
disp(pressurePreprocessedSummaryTable); %[output:0c5bcc45]
% clear campaign VH2D_Wk22 converted aligned offsetCorrected
%%
%[text] ## 6. Export Data Preparation File
%[text] ### 6.1 DPR\_VH2D\_Wk22\_Groups\_02\_03\_04 
%[text] **Note:** DPR\_VH2D\_Wk22\_Groups\_02\_03\_04 currently uses pressurePreprocessed, but when concentration data is extracted will use concentrationPreprocessed, that will include pressure and concentration prepared data.
DPR_VH2D_Wk22_Groups_02_03_04 = pressurePreprocessed;
PreprocessedDataFolder = fullfile(projectRoot, "2-Data", "CleanData", "VH2D-Wk22");   % adjust path for your OS
if ~exist(PreprocessedDataFolder,'dir')
    mkdir(PreprocessedDataFolder);
end
% check variable exists
if exist('DPR_VH2D_Wk22_Groups_02_03_04','var')
    save(fullfile(PreprocessedDataFolder,'DPR_VH2D_Wk22_Groups_02_03_04.mat'), ...
        'DPR_VH2D_Wk22_Groups_02_03_04','-v7.3');
else
    error('Variable DPR_VH2D_Wk22_Groups_02_03_04 does not exist in the workspace.');
end
%[text] ### 6.2 Gas Mixing Table Overview
% --- Save gasMixingTable as MAT only ---
if exist('gasMixingTable','var')
    customName = 'gasMixingTable_VH2D_Wk22_Groups_02_03_04.mat';
    save(fullfile(PreprocessedDataFolder,customName), 'gasMixingTable', '-v7.3');
else
    warning('Variable gasMixingTable does not exist in the workspace; nothing saved.');
end
%[text] ### 6.3 Sensor Mapping Table Overview
% --- Save sensorMappingTable as MAT only ---
if exist('sensorMappingTable','var')
    customName = 'sensorMappingTable_VH2D_Wk22_Groups_02_03_04.mat';
    save(fullfile(PreprocessedDataFolder,customName), 'sensorMappingTable', '-v7.3');
else
    warning('Variable sensorMappingTable does not exist in the workspace; nothing saved.');
end

